package ir.aryaei.tools;

import android.os.Bundle;
import com.getcapacitor.BridgeActivity;

public class MainActivity extends BridgeActivity {
    @Override public void onCreate(Bundle savedInstanceState) {
        registerPlugin(IranAryaeiPlugin.class);
        super.onCreate(savedInstanceState);

        // The online voice is generated by Microsoft's remote neural speech
        // service (WebSocket), not Android TextToSpeech or browser SpeechSynthesis.
        // The service requires an Edg token in the WebView handshake User-Agent.
        try {
            android.webkit.WebView webView = getBridge() != null ? getBridge().getWebView() : null;
            if (webView != null && webView.getSettings() != null) {
                String ua = webView.getSettings().getUserAgentString();
                if (ua == null || !ua.contains("Edg/")) {
                    webView.getSettings().setUserAgentString(
                        (ua == null ? "" : ua) + " Edg/143.0.0.0"
                    );
                }
            }
        } catch (Throwable ignored) {
            // Keep app startup safe if the WebView UA cannot be customized.
        }
    }
}
